import React from 'react';

const Reports = () => {
  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-bold text-gray-900">Reports</h1>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="card p-6 hover:shadow-lg cursor-pointer transition-shadow">
          <h3 className="font-semibold text-gray-800">Patient Reports</h3>
          <p className="text-sm text-gray-500 mt-1">View patient statistics</p>
        </div>
        <div className="card p-6 hover:shadow-lg cursor-pointer transition-shadow">
          <h3 className="font-semibold text-gray-800">Financial Reports</h3>
          <p className="text-sm text-gray-500 mt-1">Revenue and payments</p>
        </div>
        <div className="card p-6 hover:shadow-lg cursor-pointer transition-shadow">
          <h3 className="font-semibold text-gray-800">Pharmacy Reports</h3>
          <p className="text-sm text-gray-500 mt-1">Stock and sales</p>
        </div>
      </div>
    </div>
  );
};

export default Reports;
